-- v32.1.0 — Supabase Curator Persistence Schema
create table if not exists curator_tasks (id uuid primary key default gen_random_uuid(), workspace_id text, project_id text, task_type text not null, status text not null default 'new', severity text not null default 'medium', target_ref text, summary text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists curator_reports (id uuid primary key default gen_random_uuid(), task_id uuid references curator_tasks(id) on delete cascade, report_type text not null, payload jsonb not null default '{}'::jsonb, created_at timestamptz default now());
create table if not exists curator_events (id uuid primary key default gen_random_uuid(), task_id uuid references curator_tasks(id) on delete cascade, event_type text not null, payload jsonb not null default '{}'::jsonb, created_at timestamptz default now());
create table if not exists curator_reviews (id uuid primary key default gen_random_uuid(), task_id uuid references curator_tasks(id) on delete cascade, reviewer text, decision text not null, note text, created_at timestamptz default now());
create table if not exists curator_scores (id uuid primary key default gen_random_uuid(), task_id uuid references curator_tasks(id) on delete cascade, score_type text not null, score numeric not null, payload jsonb not null default '{}'::jsonb, created_at timestamptz default now());
create table if not exists curator_actions (id uuid primary key default gen_random_uuid(), task_id uuid references curator_tasks(id) on delete cascade, action_type text not null, status text not null default 'planned', payload jsonb not null default '{}'::jsonb, created_at timestamptz default now());
